// Unit tests (D66): Vitest in browser mode, driving a local Chrome/Edge through
// Playwright, so the DOM, MutationObserver, ResizeObserver and frames under
// test are the browser's own. CHROME_PATH chooses the browser, as for the smoke.
//
// One module the source imports by name is generated by the build itself (D36).
// The tests get the same module, generated here into the run's own artifact
// directory from the same values (the motion tokens, D65); the names the build's
// module also carries need a bundle and are left out, so a test reaching for one
// fails loudly instead of running against a stand-in.
import { defineConfig } from 'vitest/config'
import { playwright } from '@vitest/browser-playwright'
import fs from 'node:fs'
import { createRequire } from 'node:module'
import path from 'node:path'
import { motionValues } from './scripts/shared/motion-tokens.mjs'
import { generatedSource } from './scripts/virtual-modules.mjs'

// The lookup lives in the CJS helper every testing tool shares (D66). This file
// is bundled as ESM before it runs, and a static import of that helper carries
// its own `require('playwright')` into the bundle as a file URL, which the CJS
// loader cannot resolve; loading it here keeps the browser driver out of the
// config bundle.
const require = createRequire(import.meta.url)
const { findChrome } = require('./packages/testing/browser.cjs')

const executablePath = findChrome()
if (executablePath === undefined) throw new Error('vitest: no Chrome or Edge found; set CHROME_PATH')

const SRC = path.resolve(import.meta.dirname, 'packages', 'client', 'src')
const GENERATED_FILE = path.resolve(import.meta.dirname, '.debug', 'vitest', 'generated.mjs')
const tokens = JSON.parse(fs.readFileSync(path.join(SRC, 'theme', 'tokens.json'), 'utf8'))
fs.mkdirSync(path.dirname(GENERATED_FILE), { recursive: true })
fs.writeFileSync(GENERATED_FILE, `${generatedSource({ MOTION: motionValues(tokens) })}\n`)

export default defineConfig({
  // The contract package (D46) resolves the way the type check and the bundler
  // resolve it, from tsconfig.json's paths.
  resolve: {
    alias: {
      '@dsh-deepcraft/contracts': path.resolve(import.meta.dirname, 'packages/contracts/src'),
      '@dsh-deepcraft/engine': path.resolve(import.meta.dirname, 'packages/engine/src'),
      'virtual:dsh-deepcraft/generated': GENERATED_FILE,
    },
  },
  test: {
    include: ['packages/client/src/**/*.test.ts', 'packages/engine/src/**/*.test.ts'],
    // The engine runs on the skin's own vocabulary, which the tests hand over
    // the way the entry does (D73).
    setupFiles: ['packages/testing/vitest-setup.ts'],
    // Failure screenshots and other attachments are local artifacts.
    attachmentsDir: '.debug/vitest',
    // Browser mode binds a control port, and its own default (63315) falls inside
    // a Windows dynamic port exclusion on some machines: the bind fails with
    // EACCES before a single test runs. 51204 is Vitest's other default and sits
    // below the dynamic range's start, outside every exclusion seen so far.
    api: { port: 51204 },
    browser: {
      enabled: true,
      headless: true,
      provider: playwright({ launchOptions: { executablePath } }),
      instances: [{ browser: 'chromium' }],
    },
  },
})
